-- 控制库不参与业务快照/恢复替换；决定不能随active回退。
CREATE TABLE local_barrier(singleton INTEGER PRIMARY KEY CHECK(singleton=1),barrier_id TEXT NOT NULL,operation_id TEXT NOT NULL,mode TEXT NOT NULL,state TEXT NOT NULL,data_epoch TEXT NOT NULL,watermark INTEGER NOT NULL,deadline TEXT NOT NULL);
CREATE TABLE restore_runs(restore_id TEXT PRIMARY KEY,backup_id TEXT NOT NULL,source_epoch TEXT NOT NULL,target_epoch TEXT NOT NULL,barrier_id TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,runtime_revision INTEGER NOT NULL DEFAULT 0,committed_at TEXT,approved_by TEXT NOT NULL,created_at TEXT NOT NULL,progress_token_hash TEXT NOT NULL,progress_expires_at TEXT NOT NULL);
CREATE TABLE restore_decisions(decision_id TEXT PRIMARY KEY,restore_id TEXT NOT NULL UNIQUE REFERENCES restore_runs(restore_id),target_epoch TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN('switch','abort','rollback')),staged_manifest_hash TEXT NOT NULL,decided_at TEXT NOT NULL);
CREATE TABLE domain_stages(restore_id TEXT NOT NULL REFERENCES restore_runs(restore_id),owner TEXT NOT NULL,snapshot_id TEXT NOT NULL,snapshot_hash TEXT NOT NULL,state TEXT NOT NULL,last_error_code TEXT NOT NULL DEFAULT '',receipt_json TEXT NOT NULL DEFAULT '',PRIMARY KEY(restore_id,owner));
CREATE TABLE protection_journal(operation_id TEXT PRIMARY KEY,kind TEXT NOT NULL,state TEXT NOT NULL,payload_json TEXT NOT NULL,updated_at TEXT NOT NULL);
